arguments.command:
cd /tmp/sv-1a46b951d0974645a6d61d37c4ac1cf5/advanced-multi-complexity && dotnet package list --format json 2>&1 | tee after-cpm-packages.json > /dev/null && python3 -c "
import json

with open('baseline-packages.json') as f:
    base = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    pkgs = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for t in fw.get('topLevelPackages', []):
                key = (name, fw['framework'], t['id'])
                pkgs[key] = t['resolvedVersion']
    return pkgs

b = extract(base)
a = extract(after)

changes = []
unchanged = []
for key in sorted(set(b.keys()) | set(a.keys())):
    proj, fw, pkg = key
    bv = b.get(key)
    av = a.get(key)
    if bv != av:
        changes.append((proj, fw, pkg, bv or 'N/A', av or 'N/A'))
    else:
        unchanged.append((proj, fw, pkg, bv))

if changes:
    print('CHANGES:')
    for c in changes:
        print(f'  {c[0]} ({c[1]}): {c[2]} {c[3]} -> {c[4]}')
else:
    print('NO CHANGES - conversion is version-neutral for all unchanged packages')

print()
print(f'UNCHANGED: {len(unchanged)} package entries resolve identically')

# Show version-changed entries specifically
version_changes = [(c[0],c[1],c[2],c[3],c[4]) for c in changes if c[3] != 'N/A' and c[4] != 'N/A']
if version_changes:
    print()
    print('VERSION CHANGES (due to conflict resolution):')
    for v in version_changes:
        print(f'  {v[0]} ({v[1]}): {v[2]} {v[3]} -> {v[4]}')
"

